{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Cloud SQL instance is open to the internet",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The authorized network 0.0.0.0/0 permits connection attempts from any IPv4 address, unnecessarily exposing the database to internet-based attacks."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "SSL is not required for database connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The instance explicitly sets require_ssl to false, allowing database clients to connect without transport encryption and exposing credentials and data in transit."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL deletion protection is disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is explicitly disabled, allowing the operational database instance to be accidentally or maliciously destroyed through Terraform."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}\n",
  "fix_summary": "Removed the unrestricted 0.0.0.0/0 authorized network, required SSL for database connections, and enabled deletion protection. Existing restricted network access, backups, point-in-time recovery, and logging remain unchanged."
}
